begin;
update public.dining_tables set status='fechada' where status='aberta';
update public.cash_sessions set status='CLOSED' where status='OPEN';
do $$begin perform set_config('request.jwt.claim.sub',(select id::text from auth.users where lower(email)='dejandrea@gmail.com'),true);end $$;
set local role authenticated;
do $$
declare baseline numeric; acc uuid:=gen_random_uuid(); cat uuid:=gen_random_uuid(); pix uuid:=gen_random_uuid(); session uuid:=gen_random_uuid();
 pdv uuid:=gen_random_uuid(); dest uuid:=gen_random_uuid(); fresh uuid:=gen_random_uuid(); other uuid:=gen_random_uuid();
 product public.products; stock public.stock_items; c public.dining_tables; d public.dining_tables; item uuid; data jsonb; answer jsonb; sale public.cash_sales;
begin
 select id into acc from public.financial_accounts where caixa_padrao;
 select coalesce(sum(valor),0) into baseline from public.financial_entries where conta_id=acc;
 perform public.finance_config('categories',cat,'{"nome":"Fixture PDV revenue","natureza":"INCOME","ativo":true}');
 perform public.finance_config('methods',pix,'{"nome":"Fixture PDV pix","tipo":"PIX","ativo":true,"usar_pdv":false,"prazo_dias":0,"max_parcelas":1}'||jsonb_build_object('conta_padrao_id',(select id from public.financial_accounts where caixa_padrao)));
 perform public.cash_operation(session,'OPEN',jsonb_build_object('conta_id',acc,'categoria_id',cat,'valor_abertura',0));
 insert into public.stock_items(nome,unidade,bloquear_estoque_negativo) values('Fixture PDV insumo','UN',false) returning * into stock;
 answer:=public.save_product_with_stock(null,'{"nome":"Fixture Coca","unidade":"UN","custo":1,"preco_venda":10,"ativo":true}',jsonb_build_array(jsonb_build_object('stock_item_id',stock.id,'quantidade',1)));
 select * into product from public.products where id=(answer->>'id')::uuid;
 perform public.comanda_operation(pdv,'OPEN_PDV','{"identificacao":"Fixture venda"}');
 perform public.comanda_operation(pdv,'OPEN_PDV','{"identificacao":"Fixture venda"}');
 data:=jsonb_build_object('request_id',gen_random_uuid(),'total',0,'paid_total',0,'product_id',product.id,'quantidade',5);
 perform public.comanda_operation(pdv,'ADD_PRODUCT',data);perform public.comanda_operation(pdv,'ADD_PRODUCT',data);
 select * into c from public.dining_tables where id=pdv;
 if c.total_geral<>50 or c.origem<>'PDV' or (select count(*) from public.dining_table_items where codigo_mesa=c.codigo_mesa)<>1 then raise exception 'Product addition duplicated';end if;
 select id into item from public.dining_table_items where codigo_mesa=c.codigo_mesa;
 perform public.comanda_operation(pdv,'PAY',jsonb_build_object('request_id',gen_random_uuid(),'total',50,'paid_total',0,'mode','ITEMS','items',jsonb_build_array(jsonb_build_object('item_id',item,'quantidade',1)),'payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',10))));
 perform public.comanda_operation(dest,'OPEN','{"identificacao":"Fixture destino"}');
 data:=jsonb_build_object('request_id',gen_random_uuid(),'total',50,'paid_total',10,'destination_id',dest,'destination_total',0,'destination_paid_total',0,'items',jsonb_build_array(jsonb_build_object('item_id',item,'quantidade',2)));
 perform public.comanda_operation(pdv,'TRANSFER',data);perform public.comanda_operation(pdv,'TRANSFER',data);
 select * into c from public.dining_tables where id=pdv; select * into d from public.dining_tables where id=dest;
 if c.total_geral<>30 or c.paid_total<>10 or d.total_geral<>20 then raise exception 'Partial transfer broke totals';end if;
 if (select quantidade from public.dining_table_items where id=item)<>3 or (select product_id from public.dining_table_items where codigo_mesa=d.codigo_mesa)<>product.id then raise exception 'Transfer lost product or quantity';end if;
 -- Cannot transfer paid quantities or overrun the remaining money; failures roll back completely.
 begin perform public.comanda_operation(pdv,'TRANSFER',data||jsonb_build_object('request_id',gen_random_uuid(),'total',30,'destination_total',0));raise exception 'FAIL: stale destination';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=data||jsonb_build_object('request_id',gen_random_uuid(),'total',30,'destination_total',20,'items',jsonb_build_array(jsonb_build_object('item_id',item,'quantidade',3)));
 begin perform public.comanda_operation(pdv,'TRANSFER',data);raise exception 'FAIL: transferred paid items';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.comanda_operation(pdv,'PAY',jsonb_build_object('request_id',gen_random_uuid(),'total',30,'paid_total',10,'mode','VALUE','payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',5))));
 data:=data||jsonb_build_object('request_id',gen_random_uuid(),'paid_total',15,'items',jsonb_build_array(jsonb_build_object('item_id',item,'quantidade',2)));
 begin perform public.comanda_operation(pdv,'TRANSFER',data);raise exception 'FAIL: transferred more than unpaid balance';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'total',30,'paid_total',15,'identificacao','Fixture convertida','customer_codigo',null);
 answer:=public.comanda_operation(pdv,'CONVERT',data);perform public.comanda_operation(pdv,'CONVERT',data);
 if (select origem from public.dining_tables where id=pdv)<>'COMANDA' or (select paid_total from public.dining_tables where id=pdv)<>15 then raise exception 'Conversion lost receipts';end if;
 -- Transfers between comandas to a new identified destination.
 select id into item from public.dining_table_items where codigo_mesa=d.codigo_mesa;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'total',20,'paid_total',0,'destination_id',fresh,'new_destination',true,'identificacao','Fixture nova','items',jsonb_build_array(jsonb_build_object('item_id',item,'quantidade',2)));
 perform public.comanda_operation(dest,'TRANSFER',data);perform public.comanda_operation(dest,'TRANSFER',data);
 if (select total_geral from public.dining_tables where id=fresh)<>20 or (select total_geral from public.dining_tables where id=dest)<>0 then raise exception 'Comanda to new comanda failed';end if;
 -- Sale numbering, stock, close retry, cancel/reopen and stock restoration.
 data:=jsonb_build_object('request_id',gen_random_uuid(),'total',30,'paid_total',15,'payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',15)));
 perform public.comanda_operation(pdv,'CLOSE',data);perform public.comanda_operation(pdv,'CLOSE',data);
 if (select saldo from public.stock_items where id=stock.id)<>-3 then raise exception 'Sale stock not deducted exactly once';end if;
 select * into sale from public.cash_sales where comanda_id=pdv;
 if sale.number<>1 then raise exception 'Transfer consumed sale sequence';end if;
 data:=jsonb_build_object('request_id',gen_random_uuid(),'motivo','Fixture reabrir');
 answer:=public.cash_sale_operation(sale.id,'REOPEN',data);perform public.cash_sale_operation(sale.id,'REOPEN',data);
 other:=(answer->>'comanda_id_aberta')::uuid;
 if (select saldo from public.stock_items where id=stock.id)<>0 then raise exception 'Reopening did not restore stock';end if;
 select * into c from public.dining_tables where id=other;
 if (select count(*) from public.dining_table_items where codigo_mesa=c.codigo_mesa and product_id=product.id)<>1 then raise exception 'Reopening lost product links';end if;
 perform public.comanda_operation(other,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',30,'paid_total',0,'payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',30))));
 perform public.cash_sale_operation(sale.id,'CANCEL',jsonb_build_object('request_id',gen_random_uuid(),'motivo','Fixture cancelar'));
 if (select saldo from public.stock_items where id=stock.id)<>0 then raise exception 'Cancel did not restore stock';end if;
 -- Fully transferring an unpaid PDV ends its draft, without a sale.
 other:=gen_random_uuid();
 perform public.comanda_operation(other,'OPEN_PDV','{"identificacao":"Fixture tudo"}');
 perform public.comanda_operation(other,'ADD_PRODUCT',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'paid_total',0,'product_id',product.id,'quantidade',1));
 select * into c from public.dining_tables where id=other;
 select id into item from public.dining_table_items where codigo_mesa=c.codigo_mesa;
 perform public.comanda_operation(other,'TRANSFER',jsonb_build_object('request_id',gen_random_uuid(),'total',10,'paid_total',0,'destination_id',dest,'destination_total',0,'destination_paid_total',0,'items',jsonb_build_array(jsonb_build_object('item_id',item,'quantidade',1))));
 if (select status from public.dining_tables where id=other)<>'fechada' or exists(select 1 from public.cash_sales where comanda_id=other) then raise exception 'Transferred PDV draft created a sale or stayed open';end if;
 other:=gen_random_uuid();
 perform public.comanda_operation(other,'OPEN_PDV','{"identificacao":"Fixture bloqueio"}');
 begin perform public.comanda_operation(other,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'paid_total',0,'payments','[]'::jsonb));raise exception 'FAIL: empty PDV finalized';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 update public.stock_items set bloquear_estoque_negativo=true where id=stock.id;
 perform public.comanda_operation(other,'ADD_PRODUCT',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'paid_total',0,'product_id',product.id,'quantidade',1));
 begin perform public.comanda_operation(other,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',10,'paid_total',0,'payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',10))));raise exception 'FAIL: rigid stock allowed negative';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 if (select paid_total from public.dining_tables where id=other)<>0 or exists(select 1 from public.cash_sales where comanda_id=other) then raise exception 'Stock failure did not roll back the sale and payments';end if;
 begin perform app_private.comanda_operation_base(dest,'OPEN','{}');raise exception 'FAIL: base is executable';exception when insufficient_privilege then null;end;
end $$;
reset role;
do $$begin perform set_config('request.jwt.claim.sub','',true);end $$;
set local role authenticated;
do $$begin
 begin perform public.comanda_operation(gen_random_uuid(),'OPEN_PDV','{"identificacao":"Intruso"}');raise exception 'FAIL: unauthenticated PDV';exception when insufficient_privilege then null;end;
end $$;
rollback;
